                                <div class="v5-bullet-text"><strong class="lead-purple">ธุรกรรมการค้า 5 ประเภทหลัก:</strong> <span class="glossary-term" data-glossary="B2B">B2B</span> (ธุรกิจ-ธุรกิจ), <span class="glossary-term" data-glossary="B2C">B2C</span> (ธุรกิจ-ผู้บริโภค), <span class="glossary-term" data-glossary="C2C">C2C</span> (ผู้บริโภค-ผู้บริโภค), <span class="glossary-term" data-glossary="C2B">C2B</span> (ผู้บริโภค-ธุรกิจ) และ <span class="glossary-term" data-glossary="B2G">B2G</span> (ธุรกิจ-ภาครัฐ)</div>
